import sqlite3

def create_demo():
    # Python3.12+ explicit SQL transaction mode; MEMORY database is NOT durable.
    db=sqlite3.connect(":memory:",autocommit=True)
    db.execute("CREATE TABLE events(seq INTEGER PRIMARY KEY, version INTEGER, source TEXT, delta INTEGER)")
    db.execute("CREATE TABLE projection(id INTEGER PRIMARY KEY CHECK(id=1), through_seq INTEGER, value INTEGER)")
    db.execute("INSERT INTO projection VALUES(1,0,10)")
    return db

def append_demo(db,event,fail_stage=None):
    # Accept only a private database created/owned by create_demo(),one caller.
    if type(event) is not tuple or len(event)!=4:
        raise ValueError("invalid event shape")
    version,seq,source,delta=event
    if (type(version) is not int or version!=1 or type(seq) is not int or not 1<=seq<=16
        or type(source) is not str or source!="SIM1" or type(delta) is not int or not -10<=delta<=10):
        raise ValueError("invalid event fields")
    if fail_stage not in (None,"insert","projection"):
        raise ValueError("invalid injection stage")
    db.execute("BEGIN IMMEDIATE")
    try:
        old=db.execute("SELECT version,seq,source,delta FROM events WHERE seq=?",(seq,)).fetchone()
        if old is not None:
            if old!=event:raise ValueError("conflicting sequence content")
            db.execute("COMMIT")
            return "duplicate"
        through,value=db.execute("SELECT through_seq,value FROM projection WHERE id=1").fetchone()
        if seq!=through+1:raise ValueError("noncontiguous event")
        updated=value+delta
        if not 0<=updated<=100:raise ValueError("count invariant")
        db.execute("INSERT INTO events VALUES(?,?,?,?)",(seq,version,source,delta))
        if fail_stage=="insert":raise RuntimeError("injected after insert")
        db.execute("UPDATE projection SET through_seq=?,value=? WHERE id=1",(seq,updated))
        if fail_stage=="projection":raise RuntimeError("injected after projection")
        db.execute("COMMIT")
        return "appended"
    except Exception:
        if db.in_transaction:db.execute("ROLLBACK")
        raise

db=create_demo()
try:
    print(append_demo(db,(1,1,"SIM1",2)))
    try:append_demo(db,(1,2,"SIM1",3),"projection")
    except RuntimeError:print("rolled back")
    print(db.execute("SELECT count(*) FROM events").fetchone()[0],db.execute("SELECT through_seq,value FROM projection").fetchone())
    print(append_demo(db,(1,2,"SIM1",3)))
    print(append_demo(db,(1,2,"SIM1",3)))
    print(db.execute("SELECT through_seq,value FROM projection").fetchone())
finally:db.close()
